class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def modify(root):
    current_sum = [0]

    def reverse_inorder(node):
        if not node:
            return
        reverse_inorder(node.right)
        current_sum[0] += node.data
        node.data = current_sum[0]
        reverse_inorder(node.left)

    reverse_inorder(root)
    return root
